// === Tab: trees ===


class TreeLayer {

	constructor(j,minGroundHeight, maxGroundHeight, minTreeHeight, maxTreeHeight, numTrees){
		this.canvas = createGraphics(width,height);
		this.seed = 200*j;
		this.x = 0;

		this.minGroundHeight = minGroundHeight;
		this.maxGroundHeight = maxGroundHeight;
		this._drawGround(minGroundHeight, maxGroundHeight, j*200);	

		for(let i = 0; i < numTrees; i++) {
			// random height, bigger for foreground
			let h = random(minTreeHeight, maxTreeHeight);
			let x = random(width);

			var y = random(minGroundHeight-maxTreeHeight/2, this._groundHeight(x));
			pine(this.canvas, x, height-y, h/2, h);
			pine(this.canvas, x+width, height-y, h/2, h);
			pine(this.canvas, x-width, height-y, h/2, h);
		}
	}

	_groundHeight(x){
		//we want the height to be periodic
		var angle = TAU*x/width;
		var preHeight = noise(this.seed, Math.cos(angle), Math.sin(angle));
		return map(preHeight, 0,1, this.minGroundHeight, this.maxGroundHeight);
	}

	_drawGround(minHeight, maxHeight, seed){
		var resolution = 1000;
		this.canvas.fill(220);
		this.canvas.noStroke();
		//draw ground
		this.canvas.beginShape();
		this.canvas.vertex(width,height);
		this.canvas.vertex(0,height);
		for (let i=0; i<=resolution; i++){
			var x = width*i/resolution;
			var h = height-this._groundHeight(x);
			this.canvas.vertex(x, h);
		}
		this.canvas.endShape(CLOSE);
	}

	draw(){
		image(this.canvas,-this.x,0);
		image(this.canvas,width-this.x,0);
	}

	update(dx){
		this.x+=dx;
		if (this.x>width)
			this.x-=width;
	}

}

//draws a pine based at x,y with the given width and height w and h.
function pine(canvas,x, y, w, h) {
	canvas.push();
	canvas.translate(x,0);


  canvas.stroke(0, 20, 0);
  canvas.noFill();

  let y0 = y - h; //tree top
  canvas.strokeWeight(2.5);
  canvas.line(0, y, 0, y0);

  let di = random(1, 7);
  canvas.strokeWeight(1);
  for (let i = y0; i < y; i += (Math.max(0.001, Math.abs(di)) || 1)) {
    let l = map(i, y0, y, 0, w);
    branch(canvas, i, l);
  }

	canvas.pop();
}

function branch(canvas, y, l) {
  for (let i = 0; i < 10; i++) {
    let dy = random(-2, 5);
    let dl = random(1);
    canvas.bezier(- dl*0.50*l, y + dy,
           - dl*0.1*l, y,
           + dl*0.9*l, y,
           + dl*0.22*l, y + dy);
  }
}

