	var treeHeight = height/180;
	var treeHeightDiff = height/60;
	for (let i=0; i<layers; i++){
		var p = i/layers;
		//var canvas = createGraphics(width,height);
		var maxGroundHeight = height*(0.75*(1-p)+0.33*p);
		var minGroundHeight = height*(0.5*(1-p)+0.25*p);
		var minTreeHeight = treeHeight+treeHeightDiff*i;
		var maxTreeHeight = treeHeight+treeHeightDiff*(1+i)
		var numTrees = width*(maxGroundHeight-minGroundHeight)/(maxTreeHeight*maxTreeHeight);
		var layer = new TreeLayer(i,
															minGroundHeight, maxGroundHeight,   
															minTreeHeight, maxTreeHeight, 
															numTrees); 				
		treeLayers.push(layer);
	}
}

